def rotate(adj, n_new=100):
    n = len(adj)
    delta_n = n_new - n
    assert delta_n > 0
    candidate_n_nonaxis = np.arange(1, min(delta_n, n) + 1)
    candidate_n_nonaxis = candidate_n_nonaxis[delta_n % candidate_n_nonaxis == 0]
    assert len(candidate_n_nonaxis) >= 1
    n_nonaxis = np.random.choice(candidate_n_nonaxis)
    nonaxis = np.random.choice(np.arange(n), size=n_nonaxis, replace=False)
    assert len(nonaxis) == n_nonaxis
    is_nonaxis = np.zeros(n, dtype=bool)
    is_nonaxis[nonaxis] = True
    axis = np.arange(n)[~is_nonaxis]
    n_axis = len(axis)
    assert n_axis + n_nonaxis == n
    n_rotate = delta_n // n_nonaxis + 1
    assert n_axis + n_nonaxis * n_rotate == n_new

    true_rate = np.random.rand()
    nonaxis_adj = np.random.rand(n_rotate, n_nonaxis, n_nonaxis) < true_rate
    nonaxis_adj[0] = adj[nonaxis][:, nonaxis]
    half = nonaxis_adj[1 : (n_rotate + 1) // 2]
    nonaxis_adj[(n_rotate + 2) // 2 :] = half[::-1].transpose(0, 2, 1)
    if n_rotate % 2 == 0:
        tmp = nonaxis_adj[n_rotate // 2]
        tmp[:] = np.triu(tmp) | np.triu(tmp, k=1).T
    nonaxis_adj = nonaxis_adj.transpose(1, 0, 2).reshape(
        n_nonaxis, n_rotate * n_nonaxis
    )

    res = np.zeros((n_new, n_new), dtype=bool)
    res[:n_axis, :n_axis] = adj[axis][:, axis]
    tmp = res[:n_axis, n_axis:].reshape(n_axis, n_rotate, n_nonaxis)
    tmp[:] = adj[axis][:, nonaxis][:, None, :]
    tmp = res[n_axis:, :n_axis].reshape(n_rotate, n_nonaxis, n_axis)
    tmp[:] = adj[nonaxis][:, axis]

    for i in range(n_rotate):
        l = n_axis + i * n_nonaxis
        r = n_axis + (i + 1) * n_nonaxis
        res[l:r, n_axis:] = np.roll(nonaxis_adj, i * n_nonaxis, axis=1)
    return res


def merge(adj1, adj2):
    n1 = len(adj1)
    n2 = len(adj2)
    n = n1 + n2
    res = np.zeros((n, n), dtype=bool)
    res[:n1, :n1] = adj1
    res[n1:, n1:] = adj2
    inter_connection = np.random.rand() < 0.5
    res[:n1, n1:] = inter_connection
    res[n1:, :n1] = inter_connection
    return res


def rand_graph(n, rand_seed=None):
    if rand_seed is not None:
        np.random.seed(rand_seed)
    seed = np.array([[False]])
    seeds = [seed]
    while True:
        r = np.random.rand()
        if r < 0.2:  # add seed
            if len(seeds) != 1 or len(seeds[0]) >= n:
                continue
            seeds.append(seed)
        elif r < 0.95:  # rotate
            current_sum_n = sum(len(s) for s in seeds)
            if current_sum_n == n:
                continue
            assert current_sum_n < n
            idx = np.random.randint(len(seeds))
            current_n = len(seeds[idx])
            max_n = n - current_sum_n + current_n
            n_new = np.random.randint(current_n + 1, max_n + 1)
            new_adj = rotate(seeds[idx], n_new)
            seeds[idx] = new_adj
        else:  # merge
            if len(seeds) == 1:
                continue
            seeds = [merge(seeds[0], seeds[1])]

        if len(seeds) == 1 and len(seeds[0]) >= n:
            return seeds[0]


def edges_to_adjacency_matrix(edges, N):
    res = np.zeros((N, N), dtype=bool)
    res[~np.tri(N, dtype=bool)] = edges
    res ^= res.T.copy()
    return res


def adjacency_matrix_to_edges(adj):
    return adj[~np.tri(len(adj), dtype=bool)]


def op_linear(weight, bias, x):
    return x @ weight.T + bias


def op_attention(weight, bias, x, adj):
    # x: [batch_size, n_vertices, channels]
    # adj: [batch_size, n_vertices, n_vertices]
    b, n, ch = x.shape
    adj = adj.astype(np.float32)
    eye = np.eye(n)
    inv_adj = 1.0 - eye - adj
    mask = np.concatenate([inv_adj, adj], axis=2).reshape(b, n, 2 * n)
    q, k, v = np.split(
        op_linear(weight, bias, x)
        .reshape(b, n, 5, ch)
        .transpose(0, 2, 1, 3)
        .reshape(b, 5 * n, ch),
        [n, n * 3],
        axis=1,
    )
    qk = np.matmul(q, k.transpose(0, 2, 1)) * (1.0 / math.sqrt(ch))
    assert qk.shape == (b, n, 2 * n)
    qk += (mask - 1.0) * 1e10
    qk = scipy.special.softmax(qk, axis=2) * mask
    qkv = np.matmul(qk, v)
    # [batch_size, n_vertices, channels]
    return qkv


def op_feed_forward(weight1, bias1, weight2, bias2, x):
    return op_linear(weight2, bias2, np.maximum(0.0, op_linear(weight1, bias1, x)))


def op_fast_head(weight1, bias1, weight2, bias2, x):
    return op_linear(
        weight2,
        bias2,
        np.maximum(0.0, op_linear(weight1, bias1, x)).sum(1)
        * (1.0 / math.sqrt(x.shape[1])),
    )


class NpModel:
    def __init__(self, data):
        l, r = 0, 100 * 32
        self.embedding_dim = data[l:r].reshape(100, 32)
        l, r = r, r + 41 * 32
        self.embedding_eps = data[l:r].reshape(41, 32)
        l, r = r, r + 101 * 32
        self.embedding_n = data[l:r].reshape(101, 32)
        self.attentions = []
        for _ in range(4):
            l = r
            r1 = l + 160 * 32
            r = r1 + 160
            self.attentions.append((data[l:r1].reshape(160, 32), data[r1:r]))
        self.feed_forwards = []
        for _ in range(5):
            l = r
            r1 = l + 32 * 32
            r2 = r1 + 32
            r3 = r2 + 32 * 32
            r = r3 + 32
            self.feed_forwards.append(
                (
                    data[l:r1].reshape(32, 32),
                    data[r1:r2],
                    data[r2:r3].reshape(32, 32),
                    data[r3:r],
                )
            )
        self.fast_head = self.feed_forwards.pop()
        assert len(data) == r

    def forward(self, adj, eps_int):
        # adj: [batch_size, n_vertices, n_vertices]
        # eps_int: [batch_size]
        dims = adj.sum(1)
        x = self.embedding_dim[dims]
        x += self.embedding_eps[eps_int][:, None, :]
        x += self.embedding_n[adj.shape[1]]
        for i, (attention, feed_forward) in enumerate(
            zip(self.attentions, self.feed_forwards)
        ):
            x += op_attention(*attention, x, adj)
            if i == 3:
                x_fast = op_fast_head(*self.fast_head, x)
            x += op_feed_forward(*feed_forward, x)
        # [batch_size, n_vertices, channels], [batch_size, channels]
        return x, x_fast


