def solve_lap_greedy(arr):
    arr = arr.copy()
    N = len(arr)
    res = 0.0
    for x in range(N):
        y = arr[: N - x, x].argmin()
        res += arr[y, x]
        arr[y] = arr[N - x - 1]
    return res


def get_book(N, eps_int, M):
    # fmt: off
    dict_codes = {
        (4, 0): b"AAECAwQFBgcICQAK",
        (5, 0): b"AAECAwQFBgcICQAKAAsADAANAA4ADwAQABEAEgATABQAFQAWABcAGAAZABoAGwAcAB0AHgAfACAAIQ==",
        (6, 0): b"",
        (6, 2): b"",
        (7, 2): b"",
        (8, 2): b"",
        (7, 5): b"",
        (8, 5): b"",
        (8, 8): b"",
        (8, 11): b"",
    }
    # fmt: on

    book_raw = np.frombuffer(
        base64.b64decode(dict_codes[(N, eps_int)]), dtype=np.int8
    ).tolist()
    res = []
    appended = False
    for m in reversed(book_raw):
        if m < M and not appended:
            res.append(m)
            appended = True
        if m < 10:
            appended = False
    assert len(res) == dict_N_to_n_iso_graphs[N]
    return res[::-1]


def solve_small_N(M, eps_int, N):
    if eps_int == 0:
        pass
    elif eps_int <= 3:
        eps_int = 2
    elif eps_int <= 6:
        eps_int = 5
    elif eps_int <= 9:
        eps_int = 8
    else:
        eps_int = 11
    # fmt: off
    dict_represent_points = {
        (4, 0): (66, b"AIKLSZabef/A"),
        (5, 0): (340, b"AAQBIEoSyIIowTIMkyjLNM2DZNo2zeN9UlYVpW3Hc5z2adp23ffp+3//8A=="),
        (6, 0): (1500, b"CIARIEIAhKGAIxBGJQxLERQyKGYAzBGZAzJGZQzSGbQzfIRBSCKRBTAKZRTLIbBSSKaRTYKbJTaKbZwHOI5xPMYRjKORJzBOYRzDOZBzJOZRzLOY5jaMbZzaObZzeOb5lTMrRlbOjR1TOrZlfOrx1fO4R3DO5B3KO5Z3HO5x3PO7J3aO753zO/B36O/Z3/UqS0ZWqS1YWrS3SW6a3ZeH7x+eP7z5efTz7ef7XSa7T3ffzb/af7z/ff////A="),
        (6, 2): (1500, b"UqTw/OA///MYR34AAARLa7YzfW7xyJIRBlfWrYzYc7RlYf7IiLefJ3/KYZ3LGAIhKMbZ0TWjJTaf7xxPGbJ3SGbxDYEID/feP4RKO4ZTLKSR36W74zACID3/ObzXSGaQzKW7IzTWzZyPMbRSCO/ZzbOYIRIef5TZWrBzHGZZTIGRJ1fe6ZSKWrR3IOrC3SfzZ0aERRlbKSZ3ZObJxOOrRlTOYZzLGRZ2POrx1TOZRTROZC3TO+ZTbO4R3OA="),
        (7, 2): (2100, b""),
        (8, 2): (2800, b""),
        (7, 5): (2100, b""),
        (8, 5): (2800, b""),
        (8, 8): (2800, b""),
        (8, 11): (2800, b""),
    }
    # fmt: on
    count, edgess = dict_represent_points[(N, eps_int)]
    edgess = np.frombuffer(base64.b64decode(edgess), dtype=np.uint8)
    edgess = np.unpackbits(edgess, count=count).reshape(-1, N * (N - 1) // 2)[:M]
    print(N)
    for edges in edgess:
        print_edges(edges)

    if N == 8:
        mappings = [
            np.fromfile(f"graph_to_iso_graph_8_{i}.bin", dtype=np.int16)
            for i in range(4)
        ]
    else:
        mappings = [np.fromfile(f"graph_to_iso_graph_{N}.bin", dtype=np.int16)]
    book = get_book(N, eps_int, M)  # 12346
    for _ in range(100):
        s = input()
        edge_id = int(s[::-1], 2)
        represent_edge_id = mappings[edge_id // (1 << 26)][edge_id % (1 << 26)]
        predicted_label = book[represent_edge_id]
        print(predicted_label)


